{"command":"python3 -c '
import re

def expand_replacement(tokens, match):
    res = []
    num_groups = len(match.groups())
    group_dict = match.groupdict()

    for token_type, val in tokens:
        if token_type == "literal":
            res.append(val)
        elif token_type == "group_num":
            if val == 0:
                res.append(match.group(0))
            elif 1 <= val <= num_groups:
                g = match.group(val)
                if g is not None:
                    res.append(g)
        elif token_type == "group_name":
            if val in group_dict:
                g = group_dict[val]
                if g is not None:
                    res.append(g)

    return b"".join(res)

pattern = re.compile(b"(?P<first>a)(b)(c)")
match = pattern.search(b"abc")

tokens = [("group_num", 0), ("literal", b" "), ("group_num", 1), ("literal", b" "), ("group_name", "first")]
print(expand_replacement(tokens, match))
'"}

