                            sys.stderr.write(f"error: unexpected argument '-{ch}' found\n\n  tip: to pass '-{ch}' as a value, use '-- -{ch}'\n\nUsage: {prog} [OPTIONS] <FIND> <REPLACE_WITH> [FILES]...\n\nFor more information, try '--help'.\n")
                            sys.exit(2)
                        ch_idx += 1
                    idx += 1
                    continue
                else:
                    sys.stderr.write(f"error: unexpected argument '{arg}' found\n\n  tip: to pass '{arg}' as a value, use '-- {arg}'\n\nUsage: {prog} [OPTIONS] <FIND> <REPLACE_WITH> [FILES]...\n\nFor more information, try '--help'.\n")
                    sys.exit(2)

        positionals.append(arg)
        idx += 1

    if len(positionals) < 1:
        sys.stderr.write(f"error: the following required arguments were not provided:\n  <FIND>\n  <REPLACE_WITH>\n\nUsage: {prog} <FIND> <REPLACE_WITH> [FILES]...\n\nFor more information, try '--help'.\n")
        sys.exit(2)
    elif len(positionals) < 2:
        sys.stderr.write(f"error: the following required arguments were not provided:\n  <REPLACE_WITH>\n\nUsage: {prog} <FIND> <REPLACE_WITH> [FILES]...\n\nFor more information, try '--help'.\n")
        sys.exit(2)

    find_str = positionals[0]
    replace_str = positionals[1]
    files = positionals[2:]

    # Path existence pre-validation
    if files:
        for fpath in files:
            if not os.path.lexists(fpath) or not os.path.exists(fpath):
                sys.stderr.write(f"error: invalid path: {fpath}\n")
                sys.exit(1)

    # Process flags
    case_insensitive = False
    multiline = True
    dotall = False
    is_word = False

    if flags_arg:
        for ch in flags_arg:
            if ch == "c":
                case_insensitive = False
            elif ch == "i":
                case_insensitive = True
            elif ch == "m":
                multiline = True
            elif ch == "e":
                multiline = False
            elif ch == "s":
                dotall = True
            elif ch == "w":
                is_word = True

    find_bytes = find_str.encode("utf-8")
    if fixed_strings:
        pattern_bytes = re.escape(find_bytes)
    else:
        pattern_bytes = find_bytes

    if is_word:
        pattern_bytes = b"\\b" + pattern_bytes + b"\\b"

    py_flags = 0
    if case_insensitive:
        py_flags |= re.IGNORECASE
    if multiline:
        py_flags |= re.MULTILINE
    if dotall:
        py_flags |= re.DOTALL

    try:
        pattern_re = re.compile(pattern_bytes, py_flags)
    except re.error as e:
        sys.stderr.write(f"error: invalid regex {e}\n")
        sys.exit(1)

    if fixed_strings:
        repl_bytes = replace_str.encode("utf-8")
        repl_func = lambda m: repl_bytes
    else:
        try:
            tokens = parse_replacement(replace_str)
        except AmbiguousError as e:
            spaces = " " * (e.pos + 1)
            carets = "^" * (len(e.group_num) + len(e.suffix))
            sys.stderr.write(
                f"error: The numbered capture group '${e.group_num}' in the replacement text is ambiguous.\n"
                f"hint: Use curly braces to disambiguate it '${{{e.group_num}}}{e.suffix}'.\n"
                f"{replace_str}\n"
                f"{spaces}{carets}\n"
            )
