    help_text = f"""sd v1.0.0
An intuitive find & replace CLI

Usage: {prog} [OPTIONS] <FIND> <REPLACE_WITH> [FILES]...

Arguments:
  <FIND>
          The regexp or string (if using `-F`) to search for

  <REPLACE_WITH>
          What to replace each match with. Unless in string mode, you may use captured values like
          $1, $2, etc

  [FILES]...
          The path to file(s). This is optional - sd can also read from STDIN.

          Note: sd modifies files in-place by default. See documentation for examples.

Options:
  -p, --preview
          Display changes in a human reviewable format (the specifics of the format are likely to
          change in the future)

  -F, --fixed-strings
          Treat FIND and REPLACE_WITH args as literal strings

  -n, --max-replacements <LIMIT>
          Limit the number of replacements that can occur per file. 0 indicates unlimited
          replacements

          [default: 0]

  -f, --flags <FLAGS>
          Regex flags. May be combined (like `-f mc`).

          c - case-sensitive

          e - disable multi-line matching

          i - case-insensitive

          m - multi-line matching

          s - make `.` match newlines

          w - match full words only

  -h, --help
          Print help (see a summary with '-h')

  -V, --version
          Print version
"""
    sys.stdout.write(help_text)

class AmbiguousError(Exception):
    def __init__(self, pos, group_num, suffix):
        self.pos = pos
        self.group_num = group_num
        self.suffix = suffix

def parse_replacement(repl_str: str):
    tokens = []
    i = 0
    n = len(repl_str)
    while i < n:
        ch = repl_str[i]
        if ch == "$":
            if i + 1 < n:
                next_ch = repl_str[i + 1]
                if next_ch == "$":
                    tokens.append(("literal", b"$"))
                    i += 2
                    continue
                elif next_ch == "{":
                    close_idx = repl_str.find("}", i + 2)
                    if close_idx != -1:
                        inner = repl_str[i + 2:close_idx]
                        if inner.isdigit():
                            tokens.append(("group_num", int(inner)))
                        else:
                            tokens.append(("group_name", inner))
                        i = close_idx + 1
                        continue
                    else:
                        tokens.append(("literal", b"${"))
                        i += 2
                        continue
                elif next_ch.isdigit():
                    j = i + 1
                    while j < n and repl_str[j].isdigit():
                        j += 1
                    digits_str = repl_str[i + 1:j]
                    if j < n and (repl_str[j].isalpha() or repl_str[j] == "_"):
                        k = j
                        while k < n and (repl_str[k].isalnum() or repl_str[k] == "_"):
                            k += 1
                        suffix = repl_str[j:k]
                        raise AmbiguousError(i, digits_str, suffix)
                    tokens.append(("group_num", int(digits_str)))
                    i = j
                    continue
                elif next_ch.isalpha() or next_ch == "_":
                    j = i + 1
                    while j < n and (repl_str[j].isalnum() or repl_str[j] == "_"):
                        j += 1
                    group_name = repl_str[i + 1:j]
                    tokens.append(("group_name", group_name))
                    i = j
                    continue
                else:
                    tokens.append(("literal", b"$"))
                    i += 1
                    continue
            else:
                tokens.append(("literal", b"$"))
                i += 1
                continue
        else:
            j = i + 1
            while j < n and repl_str[j] != "$":
                j += 1
            literal_str = repl_str[i:j]
            tokens.append(("literal", literal_str.encode("utf-8")))
            i = j
