    if "unterminated character set" in msg:
        desc = "unclosed character class"
    elif "missing )" in msg or "unterminated subpattern" in msg or "unbalanced parenthesis" in msg:
        desc = "unclosed group"
    elif "nothing to repeat" in msg:
